static inline void ConvertCMYKToRGB(PixelInfo *pixel) /* <=== ConvertCMYKToRGB */ 
{
  pixel->red=((QuantumRange-(QuantumScale*pixel->red*(QuantumRange-
    pixel->black)+pixel->black)));
  pixel->green=((QuantumRange-(QuantumScale*pixel->green*(QuantumRange-
    pixel->black)+pixel->black)));
  pixel->blue=((QuantumRange-(QuantumScale*pixel->blue*(QuantumRange-
    pixel->black)+pixel->black)));
}

static inline void ConvertxyYToRGB(const double low_x,const double low_y, /* <=== ConvertxyYToRGB */ 
  const double cap_Y,double *red,double *green,double *blue)
{
  double
    gamma,
    X,
    Y,
    Z;

  gamma=PerceptibleReciprocal(low_y);
  X=gamma*cap_Y*low_x;
  Y=cap_Y;
  Z=gamma*cap_Y*(1.0-low_x-low_y);
  ConvertXYZToRGB(X,Y,Z,red,green,blue);
}

static void PruneToCubeDepth(CubeInfo *cube_info,const NodeInfo *node_info) /* <=== PruneToCubeDepth */ 
{
  register ssize_t
    i;

